"use client";
import Image from "next/image";
import Link from "next/link";
import { useState, useEffect, useRef, useCallback } from "react";
import Breadcrumb from "@/components/header/breadcrumb";
import Pagination from "@/components/pagination/pagination";
import getMuseumList from "@/services/museumListService";
import { getMuseumCities } from "@/services/museumFilterOptionsService";
import MuseumListSkeleton from "./list-skeleton";
import type { MuseumFilterOptions, FilterOption } from "@/services/museumFilterOptions.types";

type Museum = {
  id: number;
  seo_url?: string;
  name: string;
  city_name?: string;
  location_name?: string;
  location_parent_name?: string;
  type?: { sid: string; name: string } | null;
  main_image?: string | null;
};

type Meta = {
  total: number;
  current_page: number;
  last_page: number;
  per_page: number;
  from?: number;
  to?: number;
};

const PER_PAGE = 20;

export default function MuseumsPage({
  initialData,
  filterOptions,
}: {
  initialData: { data: Museum[]; meta: Meta };
  filterOptions: MuseumFilterOptions;
}) {
  const [museums, setMuseums] = useState<Museum[]>(initialData.data || []);
  const [meta, setMeta] = useState<Meta>(initialData.meta);
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);

  const [nameInput, setNameInput] = useState("");
  const [selectedCountry, setSelectedCountry] = useState<FilterOption | null>(null);
  const [selectedCity, setSelectedCity] = useState<FilterOption | null>(null);
  const [availableCities, setAvailableCities] = useState<FilterOption[]>(filterOptions.cities);
  const [citiesLoading, setCitiesLoading] = useState(false);

  // committed filter state (applied on search)
  const [appliedName, setAppliedName] = useState("");
  const [appliedCountry, setAppliedCountry] = useState<FilterOption | null>(null);
  const [appliedCity, setAppliedCity] = useState<FilterOption | null>(null);

  const isFirstRender = useRef(true);

  // Ülke değişince şehirleri güncelle
  const handleCountryChange = useCallback(async (option: FilterOption | null) => {
    setSelectedCountry(option);
    setSelectedCity(null);
    setCitiesLoading(true);
    try {
      const cities = await getMuseumCities(option?.id);
      setAvailableCities(cities);
    } catch {
      setAvailableCities([]);
    } finally {
      setCitiesLoading(false);
    }
  }, []);

  const fetchMuseums = useCallback(async (
    page: number,
    name: string,
    country: FilterOption | null,
    city: FilterOption | null,
  ) => {
    setLoading(true);
    try {
      const result = await getMuseumList({
        page,
        per_page: PER_PAGE,
        filter: {
          ...(name ? { name } : {}),
          ...(country ? { location_id: country.id } : {}),
          ...(city ? { city_id: city.id } : {}),
        },
      });
      setMuseums(result.data || []);
      setMeta(result.meta);
    } catch {
      setMuseums([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    fetchMuseums(currentPage, appliedName, appliedCountry, appliedCity);
  }, [currentPage, appliedName, appliedCountry, appliedCity, fetchMuseums]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setCurrentPage(1);
    setAppliedName(nameInput);
    setAppliedCountry(selectedCountry);
    setAppliedCity(selectedCity);
  };

  const handleReset = () => {
    setNameInput("");
    setSelectedCountry(null);
    setSelectedCity(null);
    setAvailableCities(filterOptions.cities);
    setCurrentPage(1);
    setAppliedName("");
    setAppliedCountry(null);
    setAppliedCity(null);
  };

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const hasActiveFilters = appliedName || appliedCountry || appliedCity;

  const labelCls =
    "tw-block tw-text-[12px] tw-font-semibold tw-text-[#5d556c] tw-uppercase tw-tracking-[0.05em] tw-mb-1";
  const fieldCls =
    "tw-w-full tw-rounded-lg tw-border tw-border-solid tw-border-[#d6d2de] tw-bg-white tw-px-3 tw-py-2.5 tw-text-[15px] tw-text-[#14101c] tw-outline-none focus:tw-border-[#854ec9] tw-transition-colors disabled:tw-opacity-60";
  const badgeCls =
    "tw-inline-block tw-rounded-full tw-text-white tw-text-[12px] tw-px-2.5 tw-py-1";

  return (
    <main>
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-my-4 tw-font-display">
        <Breadcrumb items={[{ pageTitle: "Museums", pageUrl: "/museums" }]} />
        <h1 className="tw-text-[24px] tw-font-bold tw-text-[#14101c] tw-mb-1">
          Museums
        </h1>
        <p className="tw-text-[#5d556c] tw-mb-4">
          Discover museums around the world — explore history, art, culture and
          more.
        </p>

        {/* Filter card */}
        <form
          onSubmit={handleSearch}
          className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#eceaf1] tw-bg-white tw-shadow-sm tw-mb-4"
        >
          <div className="tw-p-4 md:tw-p-5">
            <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-12 tw-gap-3 md:tw-items-end">
              {/* Museum name */}
              <div className="md:tw-col-span-4">
                <label className={labelCls}>Museum Name</label>
                <input
                  type="text"
                  className={fieldCls}
                  placeholder="Search by name…"
                  value={nameInput}
                  onChange={(e) => setNameInput(e.target.value)}
                />
              </div>

              {/* Country */}
              <div className="md:tw-col-span-3">
                <label className={labelCls}>Country</label>
                <select
                  className={fieldCls}
                  value={selectedCountry?.id ?? ""}
                  onChange={(e) => {
                    const opt = filterOptions.countries.find((c) => String(c.id) === e.target.value) ?? null;
                    handleCountryChange(opt);
                  }}
                >
                  <option value="">All Countries</option>
                  {filterOptions.countries.map((c) => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
              </div>

              {/* City */}
              <div className="md:tw-col-span-3">
                <label className={labelCls}>City</label>
                <select
                  className={fieldCls}
                  value={selectedCity?.id ?? ""}
                  disabled={!selectedCountry || citiesLoading}
                  onChange={(e) => {
                    const opt = availableCities.find((c) => String(c.id) === e.target.value) ?? null;
                    setSelectedCity(opt);
                  }}
                >
                  <option value="">
                    {citiesLoading ? "Loading…" : "All Cities"}
                  </option>
                  {availableCities.map((c) => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
              </div>

              {/* Buttons */}
              <div className="md:tw-col-span-2 tw-flex tw-gap-2">
                <button
                  type="submit"
                  className="tw-flex-grow tw-rounded-lg tw-text-white tw-font-semibold tw-px-4 tw-py-2.5 tw-border-0 tw-cursor-pointer hover:tw-opacity-90 tw-transition-opacity"
                  style={{ backgroundColor: "#854ec9" }}
                >
                  Search
                </button>
                {(nameInput || selectedCountry || selectedCity) && (
                  <button
                    type="button"
                    className="tw-rounded-lg tw-border tw-border-solid tw-border-[#d6d2de] tw-bg-white tw-text-[#5d556c] tw-px-3 tw-py-2.5 tw-cursor-pointer hover:tw-bg-[#f5f4f7] tw-transition-colors"
                    onClick={handleReset}
                    title="Clear filters"
                  >
                    ✕
                  </button>
                )}
              </div>
            </div>

            {/* Active filter badges */}
            {hasActiveFilters && (
              <div className="tw-flex tw-flex-wrap tw-gap-2 tw-mt-3 tw-pt-3 tw-border-0 tw-border-t tw-border-solid tw-border-[#eceaf1]">
                <span className="tw-text-[#5d556c] tw-text-[13px] tw-mr-1 tw-self-center">
                  Active:
                </span>
                {appliedName && (
                  <span className={badgeCls} style={{ backgroundColor: "#854ec9" }}>
                    Name: {appliedName}
                  </span>
                )}
                {appliedCountry && (
                  <span className={badgeCls} style={{ backgroundColor: "#854ec9" }}>
                    Country: {appliedCountry.name}
                  </span>
                )}
                {appliedCity && (
                  <span className={badgeCls} style={{ backgroundColor: "#854ec9" }}>
                    City: {appliedCity.name}
                  </span>
                )}
              </div>
            )}
          </div>
        </form>
      </div>

      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-pb-10 tw-font-display">
        {loading ? (
          <MuseumListSkeleton />
        ) : museums.length === 0 ? (
          <div className="tw-text-center tw-py-12">
            <p className="tw-text-[#5d556c]">
              No museums found for the selected filters.
            </p>
            <button
              className="tw-mt-2 tw-rounded-lg tw-border tw-border-solid tw-border-[#d6d2de] tw-bg-white tw-text-[#5d556c] tw-text-[14px] tw-px-3 tw-py-1.5 tw-cursor-pointer hover:tw-bg-[#f5f4f7] tw-transition-colors"
              onClick={handleReset}
            >
              Clear Filters
            </button>
          </div>
        ) : (
          <>
            <div className="tw-grid tw-grid-cols-2 lg:tw-grid-cols-4 tw-gap-4 tw-mt-4">
              {museums.map((museum) => (
                <div
                  className="tw-flex tw-flex-col tw-h-full tw-rounded-2xl tw-border tw-border-solid tw-border-[#eceaf1] tw-bg-white tw-overflow-hidden"
                  key={museum.id}
                >
                  {museum.main_image ? (
                    <Link href={`/museum/${museum.seo_url ?? museum.id}`}>
                      <Image
                        src={museum.main_image}
                        alt={museum.name}
                        width={400}
                        height={240}
                        className="tw-w-full tw-object-cover"
                        style={{ height: 200, objectFit: "cover" }}
                        loading="lazy"
                      />
                    </Link>
                  ) : (
                    <div
                      className="tw-w-full tw-flex tw-items-center tw-justify-center tw-bg-[#f3f2f6] tw-text-[#5d556c]"
                      style={{ height: 200 }}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" fill="currentColor" viewBox="0 0 16 16">
                        <path d="M2 1a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V2a1 1 0 0 0-1-1H2zm6 1 6 3H2L8 2zm-5 4h2v7H3V6zm4 0h2v7H7V6zm4 0h2v7h-2V6z" />
                      </svg>
                    </div>
                  )}
                  <div className="tw-p-3 tw-flex tw-flex-col tw-flex-grow">
                    <Link
                      href={`/museum/${museum.seo_url ?? museum.id}`}
                      className="tw-no-underline tw-text-[#14101c]"
                    >
                      <h2 className="tw-text-[15px] tw-font-semibold tw-mb-1">
                        {museum.name}
                      </h2>
                    </Link>
                    {(museum.city_name || museum.location_name) && (
                      <p className="tw-text-[#5d556c] tw-text-[13px] tw-mb-1 tw-flex tw-items-center">
                        <svg xmlns="http://www.w3.org/2000/svg" width="11" height="11" fill="currentColor" className="tw-mr-1" viewBox="0 0 16 16">
                          <path d="M8 16s6-5.686 6-10A6 6 0 0 0 2 6c0 4.314 6 10 6 10zm0-7a3 3 0 1 1 0-6 3 3 0 0 1 0 6z"/>
                        </svg>
                        {[museum.city_name, museum.location_name].filter(Boolean).join(", ")}
                      </p>
                    )}
                    {museum.type && (
                      <span
                        className="tw-inline-block tw-w-fit tw-rounded tw-text-white tw-text-[12px] tw-px-2 tw-py-1 tw-mt-auto"
                        style={{ backgroundColor: "#854ec9" }}
                      >
                        {museum.type.name}
                      </span>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {meta.total > PER_PAGE && (
              <div className="tw-flex tw-flex-col tw-items-center tw-gap-3 sm:tw-flex-row sm:tw-justify-between tw-mt-4 tw-mb-2">
                <p className="tw-text-[#5d556c] tw-text-[13px] tw-m-0">
                  Showing {meta.from ?? (currentPage - 1) * PER_PAGE + 1}–
                  {meta.to ?? Math.min(currentPage * PER_PAGE, meta.total)} of {meta.total} museum
                  {meta.total !== 1 ? "s" : ""}
                </p>
                <Pagination
                  currentPage={currentPage}
                  totalCount={meta.total}
                  pageSize={PER_PAGE}
                  onPageChange={handlePageChange}
                />
              </div>
            )}
          </>
        )}
      </div>
    </main>
  );
}
