export default function MuseumListSkeleton() {
  return (
    <div className="tw-grid tw-grid-cols-2 lg:tw-grid-cols-4 tw-gap-4 tw-mt-4">
      {[...Array(8)].map((_, i) => (
        <div
          className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#eceaf1] tw-bg-white tw-overflow-hidden tw-animate-pulse"
          key={i}
        >
          <div className="tw-w-full tw-bg-[#e6e3ec]" style={{ height: 200 }} />
          <div className="tw-p-3">
            <div className="tw-h-[1.1rem] tw-w-4/5 tw-bg-[#e6e3ec] tw-rounded tw-mb-2" />
            <div className="tw-h-[0.85rem] tw-w-1/2 tw-bg-[#e6e3ec] tw-rounded tw-mb-2" />
            <div className="tw-h-[0.85rem] tw-w-1/3 tw-bg-[#e6e3ec] tw-rounded" />
          </div>
        </div>
      ))}
    </div>
  );
}
